// SHA-256 でハッシュ化して16進数で表示する
// ここを変えてみよう:パスワードを "password" や "haru-pass" に、ソルトの文字列を変える
import java.security.MessageDigest;
import java.util.HexFormat;

String sha256(String s) throws Exception {
    MessageDigest md = MessageDigest.getInstance("SHA-256");
    byte[] h = md.digest(s.getBytes("UTF-8"));
    return HexFormat.of().formatHex(h).substring(0, 16) + "...";
}

String pass = "123456";   // 世界で一番使われているパスワード
System.out.println("--- ソルトなし ---");
System.out.println("haru : " + sha256(pass));
System.out.println("mocha: " + sha256(pass)); // 同じ値!

System.out.println("--- ソルトあり(ユーザーごとに違う値を混ぜる)---");
System.out.println("haru : " + sha256("x7Kp" + pass));
System.out.println("mocha: " + sha256("Q2vZ" + pass)); // 別の値になる

// URL とルールの対応表(上から順に評価)
// ここを変えてみよう:2行目と3行目を入れ替える / path を "/administrator" にする
record Rule(String prefix, String need) {}

List<Rule> rules = List.of(
    new Rule("/css/", "permitAll"),
    new Rule("/admin/", "ROLE_ADMIN"),
    new Rule("/", "authenticated"));

String path = "/admin/users";
Set<String> haru = Set.of("ROLE_USER");   // ログイン済みの一般ユーザー

for (Rule r : rules) {
    if (!path.startsWith(r.prefix())) {
        continue;
    }
    boolean ok = r.need().equals("permitAll")
            || r.need().equals("authenticated")
            || haru.contains(r.need());
    System.out.println(path + " → ルール " + r.prefix()
            + " (" + r.need() + ") → " + (ok ? "許可" : "403 拒否"));
    break;  // 最初に一致したルールで終わり
}

